<template>
<el-container class="shell"><el-aside :width="appStore.sidebarCollapsed?'64px':'220px'" class="sidebar"><div class="brand">{{appStore.sidebarCollapsed?'MDM':'SimpleMDM'}}</div>
<el-menu :default-active="activeMenu" :collapse="appStore.sidebarCollapsed" router background-color="#304156" text-color="#bfcbd9" active-text-color="#409eff">
<el-menu-item index="/mdm"><el-icon><Grid/></el-icon><span>Master data</span></el-menu-item><el-menu-item index="/workflow/approvals"><el-icon><DocumentChecked/></el-icon><span>Approvals</span></el-menu-item><el-menu-item index="/integration"><el-icon><Connection/></el-icon><span>Integration</span></el-menu-item><el-menu-item index="/integration/logs"><el-icon><Tickets/></el-icon><span>Delivery logs</span></el-menu-item><el-menu-item index="/mdm-metadata"><el-icon><SetUp/></el-icon><span>Metadata</span></el-menu-item>
</el-menu></el-aside><el-container><el-header class="topbar"><div class="heading"><el-icon class="toggle" @click="appStore.toggleSidebar"><Fold v-if="!appStore.sidebarCollapsed"/><Expand v-else/></el-icon><el-breadcrumb separator="/"><el-breadcrumb-item>SimpleMDM</el-breadcrumb-item><el-breadcrumb-item>{{route.meta.title||'Master data'}}</el-breadcrumb-item></el-breadcrumb></div>
<el-dropdown><span class="account"><el-avatar :size="30">{{initial}}</el-avatar><span><b>{{displayName}}</b><small>{{roleName}}</small></span><el-icon><ArrowDown/></el-icon></span><template #dropdown><el-dropdown-menu><el-dropdown-item disabled>{{userStore.user?.username||''}}</el-dropdown-item><el-dropdown-item divided @click="logout">Logout</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
</el-header><el-main><router-view/></el-main></el-container></el-container></template>
<script setup>import{computed}from'vue';import{useRoute,useRouter}from'vue-router';import{useUserStore}from'../stores/user';import{useAppStore}from'../stores/app';const route=useRoute(),router=useRouter(),userStore=useUserStore(),appStore=useAppStore();const displayName=computed(()=>userStore.user?.real_name||userStore.user?.username||'User'),initial=computed(()=>displayName.value.slice(0,1).toUpperCase()),roleName=computed(()=>userStore.isAdmin?'Administrator':userStore.role||'User');const activeMenu=computed(()=>route.path.startsWith('/workflow')?'/workflow/approvals':route.path.startsWith('/integration/logs')?'/integration/logs':route.path.startsWith('/integration')?'/integration':route.path.startsWith('/mdm-metadata')?'/mdm-metadata':'/mdm');function logout(){userStore.logout();router.push('/login')}</script>
<style scoped>.shell{height:100vh}.sidebar{background:#304156;transition:width .2s}.brand{height:60px;color:#fff;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700}.topbar{display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #eee}.heading,.account{display:flex;align-items:center;gap:12px}.toggle{cursor:pointer;font-size:20px}.account{cursor:pointer}.account span{display:flex;flex-direction:column}.account small{color:#909399}el-main{background:#f5f7fa}</style>